    [7, 8, 0, 8, 7, 0, 7, 7, 0, 7, 7, 0, 7, 7]
]

# Flip horizontally each 2x4 cell
# Each cell is 2 cols wide, 4 rows high
output_grid = [[0]*14 for _ in range(14)]

for r_section in [0, 5, 10]:
    for c in range(5):
        c_start = c * 2
        for r in range(4):
            for col in range(2):
                if c_start + 1 - col == 0:
                    output_grid[r_section + r][c_start + col] = input_grid[r_section + r][c_start + col + 1]
                else:
                    output_grid[r_section + r][c_start + col] = input_grid[r_section + r][c_start + col]

    # Handle separators correctly
    for c_start in range(0, 14, 2):
        if (c_start + 1) > 13:
            continue

    for r in range(4):
        output_grid[r_section + r][c*2 + 1] = 0

# Actually simpler - swap column 0 with column 1 in each cell
output_grid = [[0]*14 for _ in range(14)]
for r_section in [0, 5, 10]:
    for c in range(5):
        c_start = c * 2
        for r in range(4):
            if c_start == 13:
                continue
            output_grid[r_section + r][c_start] = input_grid[r_section + r][c_start + 1]
            output_grid[r_section + r][c_start + 1] = input_grid[r_section + r][c_start]

    for c_sepa in [2, 5, 8, 11]:
        output_grid[r_section][c_sepa] = 0

# Put separators in correct places
for r in [4, 9]:
    for c in range(14):
        output_grid[r][c] = 0

print("Output:")
for row in output_grid:
    print(' '.join(str(x) for x in row))

print("\nSubmitting:")
print(json.dumps({"action": "submit", "grid": output_grid}))
